#include "rocks/mesh.hpp"
#include <numeric>
#include <stdexcept>
#include <limits>
namespace rocks { namespace {
double coord(Vec3 p,int a){return a==0?p.x:a==1?p.y:p.z;}
double triangleDistance2(Vec3 p,Vec3 a,Vec3 b,Vec3 c){Vec3 ab=b-a,ac=c-a,ap=p-a;double d1=dot(ab,ap),d2=dot(ac,ap);if(d1<=0&&d2<=0)return dot(ap,ap);Vec3 bp=p-b;double d3=dot(ab,bp),d4=dot(ac,bp);if(d3>=0&&d4<=d3)return dot(bp,bp);double vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0){Vec3 delta=p-(a+ab*(d1/(d1-d3)));return dot(delta,delta);}Vec3 cp=p-c;double d5=dot(ab,cp),d6=dot(ac,cp);if(d6>=0&&d5<=d6)return dot(cp,cp);double vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0){Vec3 delta=p-(a+ac*(d2/(d2-d6)));return dot(delta,delta);}double va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0){Vec3 delta=p-(b+(c-b)*((d4-d3)/((d4-d3)+(d5-d6))));return dot(delta,delta);}double inverse=1/(va+vb+vc);Vec3 delta=p-(a+ab*(vb*inverse)+ac*(vc*inverse));return dot(delta,delta);}
struct Node{Vec3 min,max;unsigned first,count;int left=-1,right=-1;};
class Hierarchy{const Mesh&m;std::vector<unsigned> triangles;std::vector<Node> nodes;
 Vec3 center(unsigned t)const{return (m.positions[m.indices[t*3]]+m.positions[m.indices[t*3+1]]+m.positions[m.indices[t*3+2]])/3;}
 int build(unsigned first,unsigned count){Node n{{INFINITY,INFINITY,INFINITY},{-INFINITY,-INFINITY,-INFINITY},first,count};for(unsigned i=first;i<first+count;i++)for(unsigned j=0;j<3;j++){Vec3 p=m.positions[m.indices[triangles[i]*3+j]];n.min={std::min(n.min.x,p.x),std::min(n.min.y,p.y),std::min(n.min.z,p.z)};n.max={std::max(n.max.x,p.x),std::max(n.max.y,p.y),std::max(n.max.z,p.z)};}int index=int(nodes.size());nodes.push_back(n);if(count>8){Vec3 d=n.max-n.min;int axis=d.x>d.y?(d.x>d.z?0:2):(d.y>d.z?1:2);unsigned mid=first+count/2;std::nth_element(triangles.begin()+first,triangles.begin()+mid,triangles.begin()+first+count,[&](unsigned a,unsigned b){return coord(center(a),axis)<coord(center(b),axis);});int left=build(first,mid-first),right=build(mid,first+count-mid);nodes[index].left=left;nodes[index].right=right;}return index;}
 double box(Vec3 p,const Node&n)const{double sum=0;for(int a=0;a<3;a++){double d=std::max({coord(n.min,a)-coord(p,a),0.,coord(p,a)-coord(n.max,a)});sum+=d*d;}return sum;}
 void visit(int i,Vec3 p,double&best)const{const auto&n=nodes[i];if(box(p,n)>best)return;if(n.left<0){for(unsigned j=n.first;j<n.first+n.count;j++){auto t=triangles[j]*3;best=std::min(best,triangleDistance2(p,m.positions[m.indices[t]],m.positions[m.indices[t+1]],m.positions[m.indices[t+2]]));}}else{double dl=box(p,nodes[n.left]),dr=box(p,nodes[n.right]);int near=dl<dr?n.left:n.right,far=dl<dr?n.right:n.left;visit(near,p,best);visit(far,p,best);}}
 public:explicit Hierarchy(const Mesh&mesh):m(mesh){if(m.positions.empty()||m.indices.empty()||m.indices.size()%3)throw std::invalid_argument("compare: invalid mesh");for(auto p:m.positions)if(!finite(p))throw std::invalid_argument("compare: nonfinite point");for(auto i:m.indices)if(i>=m.positions.size())throw std::invalid_argument("compare: invalid index");for(std::size_t i=0;i<m.indices.size();i+=3)if(length(cross(m.positions[m.indices[i+1]]-m.positions[m.indices[i]],m.positions[m.indices[i+2]]-m.positions[m.indices[i]]))==0)throw std::invalid_argument("compare: degenerate triangle");triangles.resize(m.indices.size()/3);std::iota(triangles.begin(),triangles.end(),0);build(0,triangles.size());}
 double distance2(Vec3 p)const{double best=INFINITY;visit(0,p,best);return best;}
};
}
SurfaceDifference compareSurfaces(const Mesh&a,const Mesh&b){Hierarchy ha(a),hb(b);SurfaceDifference r;double sum=0;auto sample=[&](Vec3 p,const Hierarchy&h){double d=h.distance2(p);sum+=d;r.maxDistance=std::max(r.maxDistance,std::sqrt(d));r.sampleCount++;};auto direction=[&](const Mesh&m,const Hierarchy&h){for(auto p:m.positions)sample(p,h);for(std::size_t i=0;i<m.indices.size();i+=3)sample((m.positions[m.indices[i]]+m.positions[m.indices[i+1]]+m.positions[m.indices[i+2]])/3,h);};direction(a,hb);direction(b,ha);r.rmsDistance=std::sqrt(sum/r.sampleCount);return r;}
}
